local function C_f()
	local button = LMG2L["Inject button_c"]
	local screenGui = LMG2L["ScreenGui_1"]
	local tweenService = game:GetService("TweenService")	
	local logo = Instance.new("ImageLabel")	
	logo.Name = "LogoAnimado"	
	logo.Parent = screenGui	
	logo.BackgroundTransparency = 1	
	logo.Image = "rbxassetid://114757227370802"	
	logo.ScaleType = Enum.ScaleType.Fit	
	logo.AnchorPoint = Vector2.new(0.5, 0.5)	
	logo.Visible = false	
	local animando = false	
	button.MouseButton1Click:Connect(function()	
		if animando then return end	
		animando = true	
		logo.Visible = true	
		logo.Size = UDim2.new(0, 0, 0, 0)	
		logo.Position = UDim2.new(0.5, 0, 0.5, 0)	
		logo.Rotation = 0	
		local aparecer = tweenService:Create(logo, TweenInfo.new(0.6, Enum.EasingStyle.Back), {	
			Size = UDim2.new(0, 236, 0, 162)	
		})	
		aparecer:Play()	
		aparecer.Completed:Wait()	
		task.wait(0.5)	
		local mover = tweenService:Create(logo, TweenInfo.new(1.2, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut), {	
			Position = UDim2.new(0, 80, 1, -230),	
			Size = UDim2.new(0, 236, 0, 162)	
		})	
		mover:Play()	
		mover.Completed:Wait()	
		task.spawn(function()	
			local t = 0	
			while logo.Visible do	
				t = t + task.wait()	
				logo.Rotation = math.sin(t * 3) * 8	
			end	
		end)	
		animando = false	
	end)	
end;
task.spawn(C_f);

